package sohal.lld.zerodha.order;import sohal.lld.zerodha.entity.Stock;import sohal.lld.zerodha.enums.OrderStatus;import sohal.lld.zerodha.enums.OrderType;import sohal.lld.zerodha.state.OpenState;import sohal.lld.zerodha.state.OrderState;import sohal.lld.zerodha.strategy.ExecutionStrategy;import sohal.lld.zerodha.user.User;public class Order {    private final String orderId;    private double price;    private ExecutionStrategy executionStrategy;    private int quantity;    private OrderType orderType;    private OrderStatus status;    private final User user;    private final Stock stock;    private final User owner;    private OrderState orderState;    public Order(String orderId, double price, int quantity, OrderType orderType, User user, Stock stock, User owner, ExecutionStrategy executionStrategy) {        this.orderId = orderId;        this.price = price;        this.quantity = quantity;        this.orderType = orderType;        this.user = user;        this.stock = stock;        this.owner = owner;        this.status = OrderStatus.OPEN;        this.orderState = new OpenState();        this.executionStrategy = executionStrategy;    }    public void cancelOrder() {        orderState.cancelOrder(this);    }    public void setState(OrderState orderState) {        this.orderState = orderState;    }    public void notifyOwner() {        if (this.owner != null) {            owner.orderStatusUpdate(this);        }    }    public void setStatus(OrderStatus orderStatus) {        this.status = orderStatus;        notifyOwner();    }    public String getOrderId() {return orderId;}    public double getPrice() {return price;}    public int getQuantity() {return quantity;}    public OrderStatus getOrderStatus() {return status;}    public OrderType getOrderType() {return orderType;}    public Stock getStock() {return stock;}    public User getUser() {return user;}    public OrderStatus getStatus() {return status;}}